"""The commands that work on datasets, as operations that run as jobs (RFC-032 step 9 P3, step 4): create, describe,
materialize, profile, split, unseal, extend, publish, the counts a held-out side may show, the pick list, the exposure
register and the field sets proposed from a source. Each is a POST on its resource and answers 202 with the job; its body
is the command's own (`evaluation_harness.<module>:body`), which prints and answers the exit code."""

from __future__ import annotations

from evaluation_harness.ops.registry import Op

OPS = (
    Op("source-preview", "work", "what a dataset source holds: its description and first items, before a dataset is made from it; writes nothing",
       "POST", "/source-previews", "evaluation_harness.source_preview:body", "",
       locks=(), required=("source",), inputs={
           "source": {"type": "string", "x-metavar": "NAME", "description": "the dataset source: folder, manifest, huggingface, kaggle, zenodo, openml, croissant, the project's own (data/dataset_sources/NAME.py) or path/to/source.py:Class", "pattern": "^[a-z0-9][a-z0-9_]*$"},
           "query": {"type": "string", "default": "{}", "description": "what to read, as JSON (each source says its keys), as dataset-create --query takes it"},
           "rows": {"type": "integer", "default": 5, "minimum": 1, "maximum": 50, "description": "how many items to show"},
       }),
    Op("dataset-create", "work", "freeze a dataset: item list + per-item sha256",
       "POST", "/datasets/{dataset}", "evaluation_harness.dataset_create:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, tool_hidden=("source_dir",), required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "lowercase_with_underscores"},
           "source_dir": {"type": "string", "format": "path", "description": "the folder the items are read from (default: the project's data/sources/<dataset id>)"},
           "glob": {"type": "string", "default": "*", "description": "which files under --source-dir are items"},
           "exclude": {"type": "array", "items": {"type": "string"}, "description": "files under --source-dir that --glob matched and are not items, a glob matched as --glob is (repeatable): an export manifest beside the items"},
           "recursive": {"type": "boolean", "description": "descend into subdirectories of --source-dir (off by default: a corpus fetched into a subdirectory of the source dir is not swallowed into this dataset)"},
           "limit": {"type": "integer", "description": "take only the first N (sorted) — a smoke cut"},
           "tag": {"type": "array", "items": {"type": "string"}, "description": "tag every item (repeatable)"},
           "description": {"type": "string", "default": "", "description": "what the dataset is"},
           "licence": {"type": "string", "description": "the dataset's licence: an id from evh licences, unknown, or LicenseRef-<name> (optional)"},
           "include_docs": {"type": "boolean", "description": "also treat README files as items (they are skipped by default)"},
           "force": {"type": "boolean", "description": "overwrite an existing dataset"},
           "from": {"type": "string", "x-metavar": "DATASET_ID", "description": "the dataset this version is made from: recorded with the items added, removed and changed"},
           "fieldset": {"type": "string", "description": "the field set (data/fields/<id>.yaml) that declares the items' fields"},
           "fields": {"type": "string", "format": "path", "description": "a .csv or .jsonl of field values, one row per item_id", "x-file": "upload"},
           "fields_from_item": {"type": "boolean", "description": "the items are JSON objects: read each field's value from the item itself (its key of the field's name, or the field's `from` JSON pointer; `reduce: count` takes a list's length); needs --fieldset, not with --fields; with --update-fields, read from the dataset's frozen items"},
           "manifest": {"type": "string", "format": "path", "description": "a .csv or .jsonl of items: item_id, source_url [, source_sha256] [, field columns]", "x-file": "upload"},
           "source": {"type": "string", "x-metavar": "NAME", "description": "read the items from a dataset source: folder, manifest, huggingface, kaggle, zenodo, openml, croissant, the project's own (data/dataset_sources/NAME.py) or path/to/source.py:Class", "pattern": "^[a-z0-9][a-z0-9_]*$"},
           "query": {"type": "string", "default": "{}", "description": "with --source: what to read, as JSON (each source says its keys; \"answer\": COLUMN names the expected answer's column)"},
           "answer_set": {"type": "string", "description": "with --source and an answer column in the query: the label set the dataset's own answers are written as (source `dataset`; default: answers), to promote to a reference with reference-promote"},
           "update_fields": {"type": "boolean", "description": "replace the field values of an existing dataset; its items must be unchanged"},
           "lineage_only": {"type": "boolean", "description": "with --from: record which dataset an existing one was made from, its items untouched (a dataset already cited by runs gains the link; its version follows from it)"},
       }),
    Op("dataset-describe", "work", "change a dataset's licence or description, never its items or version",
       "POST", "/dataset-descriptions", "evaluation_harness.dataset_describe:body", "",
       locks=(("dataset:{dataset_id}", True),), required=(), inputs={
           "dataset_id": {"type": "string", "description": "the dataset"},
           "licence": {"type": "string", "description": "an id from evh licences, unknown, LicenseRef-<name>, or none to clear it"},
           "description": {"type": "string", "description": "a new description"},
           "card": {"type": "string", "format": "path", "description": "a YAML or JSON card (from --card-template): it replaces the card", "x-file": "upload"},
           "card_template": {"type": "boolean", "description": "print the card's questions as YAML to fill"},
       }),
    Op("dataset-materialize", "work", "hash-checked working copy of a dataset",
       "POST", "/datasets/{dataset}/materialize", "evaluation_harness.materialize:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset"},
           "force": {"type": "boolean", "description": "rebuild even if it exists"},
       }),
    Op("dataset-profile", "work", "what is inside a dataset: items, lengths, the gold's shape, a link per item (text only with --with-text)",
       "POST", "/datasets/{dataset}/profile", "evaluation_harness.dataset_profile:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset"},
           "with_text": {"type": "boolean", "description": "add each item's text (only when git has committed every item's file)"},
       }),
    Op("dataset-split", "work", "split a dataset into <id>_validation and <id>_test, stable across versions",
       "POST", "/datasets/{dataset}/split", "evaluation_harness.dataset_split:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:split_locks", parts={"dataset": "dataset_id"}, required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset to split"},
           "test": {"type": "number", "description": "the test share, between 0 and 1 (or --at with --split-by time)"},
           "split_by": {"type": "string", "enum": ["hash", "time"], "default": "hash", "description": "the split rule"},
           "key": {"type": "string", "description": "an item field: hash all items with one value to one side, or the time field for --split-by time"},
           "seed": {"type": "integer", "default": 0, "description": "with --split-by hash: the seed (default 0)"},
           "at": {"type": "string", "description": "with --split-by time: the boundary, an ISO time; items at or after it are the test side (instead of --test)"},
           "seal": {"type": "boolean", "description": "seal the test side: no run, score or label on it until evh dataset-unseal --dataset-id names a candidate system with a committed hypothesis"},
           "count_by": {"type": "string", "description": "with --seal: item fields a counts-only report (evh sealed-counts) may group the held-out side by, comma-separated; fixed now, so whoever reads the counts does not choose what they show (RFC-031)"},
           "force": {"type": "boolean", "description": "overwrite the two datasets if nothing cites them yet"},
       }),
    Op("dataset-unseal", "decision", "open a sealed test side to one candidate system whose hypothesis is committed (one look)",
       "POST", "/datasets/{dataset}/unseal", "evaluation_harness.dataset_unseal:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:split_locks", why="reason", parts={"dataset": "dataset_id"}, required=("dataset_id", "system", "reason",), inputs={
           "dataset_id": {"type": "string", "description": "the sealed dataset (a split's test side)"},
           "system": {"type": "string", "description": "the candidate system: its id"},
           "reason": {"type": "string", "description": "why this candidate, and why now: a sentence"},
           "confirm_extra_look": {"type": "boolean", "description": "past the set's limit of looks (RFC-029): the person's consent to look again (an agent cannot)"},
       }),
    Op("dataset-seal-counts", "decision", "allow one more field in a held-out side's counts: a person's decision, recorded (RFC-031)",
       "POST", "/datasets/{dataset}/sealed-counts/allow", "evaluation_harness.dataset_seal_counts:body", "",
       locks=(("dataset:{dataset_id}", True),), why="reason", parts={"dataset": "dataset_id"}, required=("dataset_id", "add", "reason",), inputs={
           "dataset_id": {"type": "string", "description": "the held-out side"},
           "add": {"type": "string", "description": "the item field to allow"},
           "reason": {"type": "string", "description": "why the counts need it"},
       }),
    Op("dataset-extend", "work", "the next version of a dataset: its items and the picks you choose",
       "POST", "/datasets/{dataset}/extend", "evaluation_harness.dataset_extend:body", "",
       locks=(("dataset:{dataset_id}", True), ("picks", True)), one_of=("picks", "pick",), exclusive=(("picks", "pick",), ), required=("dataset", "dataset_id",), inputs={
           "dataset": {"type": "string", "description": "the governed dataset this version grows from (V1)"},
           "dataset_id": {"type": "string", "description": "the new version's id (V2)"},
           "picks": {"type": "boolean", "description": "every pick waiting for V1"},
           "pick": {"type": "array", "items": {"type": "string"}, "description": "one pick: ITEM, or DATASET:ITEM (repeatable)"},
           "description": {"type": "string", "description": "what this version is"},
       }),
    Op("dataset-publish", "work", "publish a dataset to a new repo (Hugging Face), private first, read back and checked by sha256",
       "POST", "/datasets/{dataset}/publish", "evaluation_harness.dataset_publish:body", "",
       locks=(("dataset:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id", "to",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset to publish"},
           "to": {"type": "string", "x-metavar": "SOURCE", "description": "the source that writes it (huggingface)", "pattern": "^[a-z0-9][a-z0-9_]*$"},
           "query": {"type": "string", "default": "{}", "description": "where to write it, as JSON (huggingface: {\"repo\": \"owner/name\"})"},
       }),
    Op("fieldset-propose", "work", "a field set proposed from a dataset source's features, for a person to accept (--write)",
       "POST", "/fieldset-proposals", "evaluation_harness.fieldset_propose:body", "",
       locks=(), required=("source", "fieldset_id",), inputs={
           "source": {"type": "string", "description": "a dataset source, as dataset-create --source names one", "pattern": "^[a-z0-9][a-z0-9_]*$"},
           "query": {"type": "string", "default": "{}", "description": "what to read, as JSON"},
           "fieldset_id": {"type": "string", "description": "the field set's id (data/fields/<id>.yaml)"},
           "sample": {"type": "integer", "default": 200, "description": "items read to find the choices (default 200)"},
           "max_choices": {"type": "integer", "default": 20, "description": "at most this many values make a choice (default 20)"},
           "write": {"type": "boolean", "description": "write data/fields/<id>.yaml; refused when it exists"},
       }),
    Op("pick", "work", "pick production items for the next version of governed datasets, or drop a pick",
       "POST", "/datasets/{dataset}/picks", "evaluation_harness.pick:body", "",
       locks=(("picks", True),), parts={"dataset": "dataset_id"}, required=("dataset_id", "item",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset the items are in (usually a production one)"},
           "item": {"type": "array", "items": {"type": "string"}, "description": "an item to pick (repeatable)"},
           "targets": {"x-flag": "--for", "type": "array", "items": {"type": "string"}, "description": "a dataset it may join (repeatable)"},
           "tag": {"type": "array", "items": {"type": "string"}, "description": "KEY=VALUE, to group candidates (repeatable)"},
           "note": {"type": "string", "default": "", "description": "why it is worth keeping"},
           "drop": {"type": "boolean", "description": "take these items off the waiting list"},
       }),
    Op("exposure-add", "work", "record reads of a held-out side's items: each is left out of every later score on it (RFC-031)",
       "POST", "/datasets/{dataset}/exposure", "evaluation_harness.exposure_add:body", "",
       locks=(("exposure:{dataset_id}", True),), parts={"dataset": "dataset_id"}, required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the held-out side"},
           "item": {"type": "array", "items": {"type": "string"}, "description": "an item read (repeatable)"},
           "what": {"type": "string", "description": "what was read: \"decision and reason\", \"label in a test fixture\", ..."},
           "at": {"type": "string", "description": "when it was read (ISO 8601; default: now)"},
           "read_by": {"type": "string", "description": "who read it: person:NAME or agent:NAME (default: who records it, as --by says)"},
           "from": {"type": "string", "format": "path", "description": "a TSV of reads (item_id, what, and optionally by, at)", "x-file": "upload"},
       }),
    Op("exposure-check", "work", "search the project's public repos for a held-out side's item ids: leaks the register lacks (RFC-031)",
       "POST", "/exposure/check", "evaluation_harness.exposure_check:body", "",
       locks=(), required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the held-out side"},
           "out": {"type": "string", "format": "path", "description": "write the leaks not in the register as a TSV for exposure-add --from", "x-file": "artifact"},
       }),
)  # fmt: skip
